namespace Game.AI.Parameters
{
    /// <summary>
    /// 迷路内の敵エージェントが使用する
    /// 能力・性格・行動傾向の識別子。
    /// </summary>
    public enum MazeEnemyParameter
    {
        /// <summary>
        /// 未指定のパラメーター。
        /// </summary>
        None = 0,

        // ========================================
        // 基本能力：100番台
        // ========================================

        /// <summary>
        /// 基本移動速度。単位はセル毎秒。
        /// </summary>
        MoveSpeed = 100,

        /// <summary>
        /// 追跡時の移動速度倍率。
        /// </summary>
        ChaseSpeedMultiplier = 101,

        /// <summary>
        /// 逃走時の移動速度倍率。
        /// </summary>
        EscapeSpeedMultiplier = 102,

        // ========================================
        // 認識能力：200番台
        // ========================================

        /// <summary>
        /// プレイヤーを認識できる距離。
        /// 単位はセル。
        /// </summary>
        DetectionRange = 200,

        /// <summary>
        /// 脅威を認識できる距離。
        /// 単位はセル。
        /// </summary>
        ThreatDetectionRange = 201,

        /// <summary>
        /// 認識対象の記憶保持時間。単位は秒。
        /// </summary>
        MemoryDuration = 202,

        /// <summary>
        /// 仮想音源を認識する基準聴覚範囲。
        /// 単位はセル。0の場合は聴覚を無効化する。
        /// </summary>
        HearingRange = 203,

        /// <summary>
        /// 仮想音源に対する聴覚感度。
        /// 範囲は0から1。
        /// </summary>
        HearingSensitivity = 204,

        /// <summary>
        /// 音源の位置を推定する精度。
        /// 範囲は0から1。
        /// </summary>
        HearingAccuracy = 205,

        // ========================================
        // 性格：300番台
        // ========================================

        /// <summary>
        /// プレイヤーへの攻撃性。
        /// </summary>
        Aggression = 300,

        /// <summary>
        /// 危険に対する警戒心。
        /// </summary>
        Caution = 301,

        /// <summary>
        /// 対象を追い続ける執着心。
        /// </summary>
        Persistence = 302,

        /// <summary>
        /// 回り込みや予測を利用する戦術的知能。
        /// </summary>
        TacticalIntelligence = 303,

        /// <summary>
        /// 自分の領域を重視する縄張り意識。
        /// </summary>
        Territoriality = 304,

        // ========================================
        // 行動傾向：400番台
        // ========================================

        /// <summary>
        /// 未探索領域への探索意欲。
        /// </summary>
        Exploration = 400,

        /// <summary>
        /// 通常巡回を選択する傾向。
        /// </summary>
        PatrolPreference = 401,

        /// <summary>
        /// 縄張りの基準範囲。単位はセル。
        /// </summary>
        TerritoryRadius = 402,

        /// <summary>
        /// セルの訪問記憶を保持する時間。
        /// 単位は秒。
        /// </summary>
        VisitMemoryDuration = 403,

        /// <summary>
        /// 対象の移動を予測する時間。
        /// 単位は秒。
        /// </summary>
        PredictionTime = 404
    }
}
